        } catch (e2) { snaps = []; }
    }
    snaps = snaps.filter(function (s) { return s && s.url; });
    snaps.unshift({
        ts: new Date().toISOString(),
        tick: (state && state.tick && state.tick.at) || '',
        stamp: stamp,
