    });
    snaps = snaps.slice(0, keep);
    exec({ command: historyPutCommand(state, cfg,
        { schema: 1, repo: repo, asset: assetName(state, cfg), snapshots: snaps },
        sha) });
    return 'https://raw.githubusercontent.com/' + repo + '/' + branch + '/' +
        indexPath;
}

