        ts: new Date().toISOString(),
        tick: (state && state.tick && state.tick.at) || '',
        stamp: stamp,
        url: 'https://raw.githubusercontent.com/' + repo + '/' + branch +
             '/data/' + base + '-' + stamp + '.json'
