function updateHistory(state, cfg, exec) {
    var repo = (cfg && cfg.repo) || state.repo;
    var branch = tagOf(cfg);
    var base = assetName(state, cfg).replace(/\.json$/, '');
    var keep = (cfg && cfg.historyKeep) || HISTORY_KEEP;
    var stamp = stampOf(state);
