    var repo = (cfg && cfg.repo) || state.repo;
    var base = assetName(state, cfg).replace(/\.json$/, '');
    var json = JSON.stringify(state);
    return 'gh api -X PUT repos/' + repo + '/contents/data/' + base + '-' +
        stamp + '.json' +
