function stampQueuePositions(lanes) {
    (lanes.approved_queue || []).forEach(function (card, i) {
        card.queuePos = i + 1;
    });
}

function copyLatchInto(carry, latch) {
    if (latch && typeof latch === 'object') {
        Object.keys(latch).forEach(function (k) { carry[k] = latch[k]; });
    }
}

