{"content":"// Probe: does cli_execute_command transport a >128KB command string?
// Builds a synthetic `gh api`-shaped command whose printf payload is
// ~130KB (> Linux MAX_ARG_STRLEN=131072 for a single execve argument)
// and one just under (100KB), and reports which survive.
function bigCmd(bytes) {
    var chunk = '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcd'; // 64B
    var s = '';
    while (s.length < bytes) s += chunk;
    return 'printf %s ' + JSON.stringify(s.slice(0, bytes)) + ' | wc -c';
}

var under = bigCmd(100 * 1024);   // 100KB — under 128KB
var over = bigCmd(130 * 1024);    // 130KB — over 128KB

var r1 = null;
try {
    r1 = cli_execute_command({ command: under });
    console.log('UNDER 100KB -> ok, wc=' + String(r1 && (r1.output || r1)).trim());
} catch (e1) {
    console.log('UNDER 100KB -> FAILED: ' + (e1.message || e1));
}

var r2 = null;
try {
    r2 = cli_execute_command({ command: over });
    console.log('OVER 130KB -> ok, wc=' + String(r2 && (r2.output || r2)).trim());
} catch (e2) {
