    } catch (e) { sha = ''; } // first publish — the file is absent
    publishCommands(state, cfg, sha).forEach(function (c) {
        exec({ command: c });
    });
    return 'https://raw.githubusercontent.com/' + repo + '/' + branch +
        '/data/' + asset;
}

