function bigCmd(bytes) {
    var chunk = '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcd'; // 64B
    var s = '';
    while (s.length < bytes) s += chunk;
    return 'printf %s ' + JSON.stringify(s.slice(0, bytes)) + ' | wc -c';
}

