{"content":"// Probe 2: whitelist-clean. `bash` is a whitelisted leading token, so the
// full command (including the giant single argument) reaches the real
// transport. Reports which payload sizes survive exec.
function bigBash(bytes) {
    var chunk = '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcd';
    var s = '';
    while (s.length < bytes) s += chunk;
    var payload = s.slice(0, bytes).replace(/'/g, '');
    return "bash -c 'printf %s " + payload + " | wc -c'";
}

[100 * 1024, 125 * 1024, 130 * 1024, 200 * 1024].forEach(function (bytes) {
    try {
        var r = cli_execute_command({ command: bigBash(bytes) });
        console.log(bytes + 'B arg -> ok, wc=' + String(r && (r.output || r)).trim());
    } catch (e) {
        console.log(bytes + 'B arg -> FAILED: ' + String(e.message || e).slice(0, 300));
    }
});
","path":"js/argLimitProbe.js"}

{"command":"which gh git; cat > js/argLimitProbe.js <<'EOF'
// Probe 3: the exact snapshotPutCommand shape. execve(gh/git) happens
// BEFORE the binary runs — exit 126 'Argument list too long' proves the
// transport limit fires for this command shape; a binary's own usage
// error (exit != 126) would prove the opposite.
function bigJson(bytes) {
    var chunk = '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcd';
    var s = '';
    while (s.length < bytes) s += chunk;
    return ('{"lanes":{"x":"' + s + '"}}').slice(0, bytes);
}

[18 * 1024, 100 * 1024, 127 * 1024].forEach(function (bytes) {
    // real shape: content="$(printf %s '<json>' | base64)" — base64 inflates 4/3
    var cmd = 'git -C / --no-pager -f content="$(printf %s ' +
        "'" + bigJson(bytes).replace(/'/g, '') + "'" + ' | base64)" --version';
    try {
        var r = cli_execute_command({ command: cmd });
        console.log('json ' + bytes + 'B -> ok: ' + String(r && (r.output || r)).trim().slice(0, 60));
    } catch (e) {
        console.log('json ' + bytes + 'B -> FAILED: ' + String(e.message || e).slice(0, 160));
    }
});
EOF
timeout 90 ~/.dmtools/bin/dmtools run /tmp/probe/probe.json 2>&1 | grep -E "json .*B ->"; echo "exit: $?"","timeout":120}

{"command":"cat > js/argLimitProbe.js <<'EOF'
// Probe 4: bisect the JSON size where snapshotPutCommand's shape E2BIGs.
function bigJson(bytes) {
    var chunk = '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcd';
    var s = '';
    while (s.length < bytes) s += chunk;
    return ('{"lanes":{"x":"' + s + '"}}').slice(0, bytes);
}
function probe(bytes) {
    var cmd = 'git -C / --no-pager -f content="$(printf %s ' +
        "'" + bigJson(bytes).replace(/'/g, '') + "'" + ' | base64)" --version';
    try {
        cli_execute_command({ command: cmd });
        return true;
    } catch (e) {
        return String(e.message || e).indexOf('126') === -1;
    }
}
var lo = 18432, hi = 131072; // lo known-good, hi known-bad (from probe 3)
while (hi - lo > 1024) {
    var mid = Math.floor((lo + hi) / 2);
    if (probe(mid)) { lo = mid; } else { hi = mid; }
}
console.log('largest OK JSON ~' + lo + 'B; smallest E2BIG JSON ~' + hi +
  'B  (base64 arg = ~' + Math.ceil(hi * 4 / 3) + 'B vs MAX_ARG_STRLEN 131072B)');
EOF
