var diff = require('child_process').execSync('git diff origin/main...HEAD -U3', {encoding:'utf8'});
var cur = null, inHunk = false, newLine = 0, ok = true;
var anchors = {};
diff.split('\n').forEach(function (l) {
  var m = l.match(/^\+\+\+ b\/(.+)$/);
  if (m) { cur = m[1]; return; }
  var h = l.match(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/);
  if (h) { inHunk = true; newLine = +h[1]; return; }
  if (!inHunk || !cur) return;
  if (l.charAt(0) === '+') { anchors[cur + ':' + newLine] = 'added'; newLine++; }
  else if (l.charAt(0) === ' ') { anchors[cur + ':' + newLine] = 'context'; newLine++; }
});
r.inlineComments.forEach(function (c) {
  var k = c.path + ':' + c.line;
