var fs = require('fs');
// 1. JSON validity + shape
var r = JSON.parse(fs.readFileSync('outputs/pr_review.json', 'utf8'));
console.log('JSON valid ✓ · recommendation:', r.recommendation, '· counts:', JSON.stringify(r.issueCounts));
var nBlock = r.inlineComments.filter(function(c){return c.severity==='BLOCKING';}).length;
console.log('blocking inline comments:', nBlock, '· cross-check with issueCounts.blocking =', r.issueCounts.blocking, '·', nBlock === r.issueCounts.blocking ? 'MATCH ✓' : 'MISMATCH ❌');
console.log('generalComment file exists:', fs.existsSync(r.generalComment) ? '✓' : '❌');
// 2. every inline anchor must appear in the PR diff (added or context line)
var diff = require('child_process').execSync('git diff origin/main...HEAD -U3', {encoding:'utf8'});
var cur = null, inHunk = false, newLine = 0, ok = true;
var anchors = {};
diff.split('\n').forEach(function (l) {
  var m = l.match(/^\+\+\+ b\/(.+)$/);
  if (m) { cur = m[1]; return; }
  var h = l.match(/^@@ -\d+(?:,\d+)? \+(\d+)(?:,(\d+))? @@/);
  if (h) { inHunk = true; newLine = +h[1]; return; }
  if (!inHunk || !cur) return;
  if (l.charAt(0) === '+') { anchors[cur + ':' + newLine] = 'added'; newLine++; }
  else if (l.charAt(0) === ' ') { anchors[cur + ':' + newLine] = 'context'; newLine++; }
});
r.inlineComments.forEach(function (c) {
  var k = c.path + ':' + c.line;
  var kind = anchors[k];
  console.log(k, kind ? ('in diff (' + kind + ') ✓') : 'NOT A DIFF LINE ❌');
  if (!kind) ok = false;
  if (!fs.existsSync(c.comment)) { console.log(c.comment, 'MISSING ❌'); ok = false; }
});
process.exit(ok ? 0 : 1);
"; echo "verify exit: $?""}

