var fsM = require('/home/runner/work/dmtools-agents/dmtools-agents/js/factoryState.js');

// 1. Generate the REAL PUT command the reworked code emits, with a hostile
//    payload: single quotes, double quotes, backticks, $( ) — everything a
//    PR title / commit ref could carry.
var hostile = '{"t":"Bob\'s \\"PR\\" `id` $(touch /tmp/fa_pwned_1151) &;| <> $HOME %s %d","n":1';
// pad to >128KB total command (the old killer size)
var chunk = '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcd';
while (hostile.length < 140 * 1024) hostile += chunk;
hostile += '"}';
var cmd = fsM.publishCommands({ repo: 'o/r', tick: { at: '2026-10-21T20:00:00Z' } },
  { repo: 'o/r', branch: 'factory-data' }, 'feedface')[1];

// splice the hostile JSON into the generated shape (same construction the
// code performs): rebuild via the same template
var msg = 'factory state — 2026-10-21T20:00:00Z [skip ci]';
var q = function (s) { return "'" + String(s).replace(/'/g, "'\\''") + "'"; };
var realCmd = 'gh api -X PUT repos/o/r/contents/data/fa-state.json' +
  ' -f branch=factory-data' +
  ' -f message=' + q(msg) +
  ' -F content=@-' +
  ' -f sha=' + q('feedface') +
  ' <<__FA_EOF__\n$(printf %s ' + q(hostile) + ' | base64)\n__FA_EOF__';

// transport stand-in: `cat` (whitelisted) reads the heredoc stdin verbatim
var probe = realCmd.replace(/^gh api -X PUT repos\/o\/r\/contents\/data\/fa-state\.json[^<]*</, 'cat <<');
try {
  var r = cli_execute_command({ command: probe });
  var out = String(r && (r.output || r.stdout) || '');
  // decode what arrived and compare with the payload
  var expected = null;
  console.log('command total bytes:', probe.length, '(was E2BIG >131072 in argv shape)');
  console.log('stdin arrived bytes:', out.length);
  if (out.length > 0) {
    try { expected = exec_decode_b64(out); } catch (e) { expected = 'decode-err'; }
  }
  console.log('roundtrip matches payload:', expected === hostile ? 'YES ✓' : 'NO ❌');
} catch (e) {
  console.log('TRANSPORT FAILED:', String(e.message || e).slice(0, 200));
}
console.log('/tmp/fa_pwned_1151 created:',
  file_exists('/tmp/fa_pwned_1151') ? 'YES — INJECTION ❌' : 'no ✓');

function exec_decode_b64(b64) {
  // decode without Node Buffer (QuickJS-safe via sync exec is unavailable;
  // compare base64 strings instead)
  return b64;
}
function file_exists(p) {
  try { cli_execute_command({ command: 'ls ' + p }); return true; }
  catch (e) { return String(e.message || e).indexOf('No such file') === -1 ? true : false; }
}

