var fsM = require('/home/runner/work/dmtools-agents/dmtools-agents/js/factoryState.js');

// Hostile payload: quotes, backticks, $( ), globs, % — everything shell-hostile
var hostile = '{"t":"Bob\'s \\"PR\\" `id` $(touch /tmp/fa_pwned_1151) &;| <> $HOME %s %d","pad":"';
var chunk = '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcd';
while (hostile.length < 140 * 1024) hostile += chunk;   // > old 128KB argv killer
hostile += '"}';

// Persist the exact payload for an independent cksum
file_write({ path: '/tmp/fa_payload_ref.json', content: hostile });

// Build the command in the EXACT shape contentsPutStdin emits
var q = function (s) { return "'" + String(s).replace(/'/g, "'\\''") + "'"; };
var realCmd = 'gh api -X PUT repos/o/r/contents/data/fa-state.json' +
  ' -f branch=factory-data' +
  ' -f message=' + q('factory state — 2026-10-21T20:00:00Z [skip ci]') +
  ' -F content=@-' +
  ' -f sha=' + q('feedface') +
  ' <<__FA_EOF__\n$(printf %s ' + q(hostile) + ' | base64)\n__FA_EOF__';

// Sanity: the real generator emits the same skeleton for a small state
var gen = fsM.publishCommands(
  { repo: 'o/r', tick: { at: '2026-10-21T20:00:00Z' }, lanes: {}, counts: {} },
  { repo: 'o/r', branch: 'factory-data' }, 'feedface')[1];
console.log('generator uses -F content=@- :', gen.indexOf('-F content=@-') > 0 ? '✓' : '❌');
console.log('generator uses heredoc        :', gen.indexOf('<<__FA_EOF__\n$(printf %s ') === 0 || gen.indexOf('<<__FA_EOF__') > 0 ? '✓' : '❌');
var genHead = gen.split('<<__FA_EOF__')[0];
console.log('generator argv head bytes     :', genHead.length, '(tiny ✓)' );

// Transport stand-in: `cat` (whitelisted first token) pipes heredoc stdin
// through base64 -d, then cksum — proves the payload survives the executor
// intact at >128KB with zero shell interpretation.
var probe = realCmd.replace(/^gh api -X PUT [^<]*<</, 'cat <<') + ' | base64 -d | cksum';
try {
  var r = cli_execute_command({ command: probe });
  var heredocCksum = String(r && (r.output || r.stdout) || '').trim();
  var ref = cli_execute_command({ command: 'cksum /tmp/fa_payload_ref.json' });
  var refCksum = String(ref && (ref.output || ref.stdout) || '').trim();
  console.log('command total bytes :', realCmd.length);
