  ' -F content=@-' +
  ' -f sha=' + q('feedface') +
  ' <<__FA_EOF__\n$(printf %s ' + q(hostile) + ' | base64)\n__FA_EOF__';

// Sanity: the real generator emits the same skeleton for a small state
