  var heredocCksum = String(r && (r.output || r.stdout) || '').trim();
  var ref = cli_execute_command({ command: 'cksum /tmp/fa_payload_ref.json' });
  var refCksum = String(ref && (ref.output || ref.stdout) || '').trim();
