  console.log('heredoc->decoded cksum :', heredocCksum);
  console.log('reference payload cksum:', refCksum);
  console.log('payload roundtrip intact:', heredocCksum === refCksum ? 'YES ✓' : 'NO ❌');
} catch (e) {
  console.log('TRANSPORT FAILED:', String(e.message || e).slice(0, 200));
}

// Injection check: the $(touch ...) in the payload must NOT have executed
var pwned = cli_execute_command({ command: 'ls /tmp/fa_pwned_1151' });
var pwnedOut = String(pwned && (pwned.output || pwned.stdout) || '');
