// Stepwise heredoc transport debugging
function run(label, cmd) {
  try {
    var r = cli_execute_command({ command: cmd });
    console.log(label, '-> ok:', JSON.stringify(String(r && (r.output || r.stdout) || '').slice(0, 80)));
  } catch (e) {
    console.log(label, '-> FAILED:', String(e.message || e).slice(0, 160));
  }
}

// 1. minimal two-line heredoc
run('tiny heredoc', 'cat <<__FA_EOF__\nhello\n__FA_EOF__');

// 2. heredoc + pipe
run('heredoc+pipe', 'cat <<__FA_EOF__ | wc -c\nhello world\n__FA_EOF__');

// 3. heredoc + command substitution body (the real shape's body)
run('heredoc+$(printf)', 'cat <<__FA_EOF__\n$(printf %s abc | base64)\n__FA_EOF__');

// 4. real shape skeleton, small payload, full pipe chain
run('shape+base64 -d+cksum', "cat <<__FA_EOF__ | base64 -d | cksum\n$(printf %s '" + "abc" + "' | base64)\n__FA_EOF__");

