function run(label, cmd) {
  try {
    var out = String(cli_execute_command({ command: cmd }) || '');
    console.log(label, '-> ALLOWED, out:', JSON.stringify(out.slice(0, 40)));
  } catch (e) {
    console.log(label, '-> REJECTED:', String(e.message || e).indexOf('not allowed') !== -1 ? 'whitelist' : String(e.message || e).slice(0, 80));
  }
}
var q = function (s) { return "'" + String(s).replace(/'/g, "'\\''") + "'"; };

// Isolate which fragment trips the whitelist (all via the same heredoc shape)
var frags = {
  'plain': 'hello',
  'dollar-paren-print': "$(printf %s abc | base64)",
  'backtick': "`id`",
  'dollar-paren-touch': "$(touch /tmp/x)",
  'amp-semi-pipe': "&;|",
  'dollar-HOME': "$HOME",
  'percent-s': "%s %d",
  'angle': "<>",
  'squote-escaped': "Bob" + String.fromCharCode(39) + "s"
};
Object.keys(frags).forEach(function (k) {
  run('frag:' + k, 'cat <<__FA_EOF__ | wc -c\n' + frags[k] + '\n__FA_EOF__');
});

// The critical real-world question: OLD accepted shape (round-2 verified)
// vs NEW heredoc shape with the SAME benign-but-quoted payload
var benign = q('{"t":"plain title","pad":"' + new Array(1000).join('a') + '"}');
run('old shape (git stand-in)', 'git -C / --no-pager -f content="$(printf %s ' + benign + ' | base64)" --version');
run('new shape (cat stand-in)', 'cat <<__FA_EOF__ | wc -c\n$(printf %s ' + benign + ' | base64)\n__FA_EOF__');

