function run(label, cmd) {
  try {
    var out = String(cli_execute_command({ command: cmd }) || '');
    console.log(label, '-> ALLOWED out:', JSON.stringify(out.slice(0, 30)));
  } catch (e) {
    var m = String(e.message || e);
    console.log(label, '->', m.indexOf('not allowed') !== -1 ? 'WHITELIST-REJECTED' : ('EXEC-FAIL: ' + m.slice(0, 60)));
  }
}
var q = function (s) { return "'" + String(s).replace(/'/g, "'\\''") + "'"; };
var chunk = '0123456789abcdef';

var benignSmall = '{"t":"plain","pad":"' + new Array(100).join('a') + '"}';
var benignBig = '{"t":"plain","pad":"' ;
while (benignBig.length < 140 * 1024) benignBig += chunk;
benignBig += '"}';
var hostileBig = '{"t":"Bob\'s `id` $(touch /tmp/x) &;| <> $HOME","pad":"';
while (hostileBig.length < 140 * 1024) hostileBig += chunk;
hostileBig += '"}';

// A: benign small, full pipe chain (base64 -d | cksum)
run('A benign-small +cksum', 'cat <<__FA_EOF__ | base64 -d | cksum\n$(printf %s ' + q(benignSmall) + ' | base64)\n__FA_EOF__');

// B: benign 140KB, same chain
run('B benign-140KB +cksum', 'cat <<__FA_EOF__ | base64 -d | cksum\n$(printf %s ' + q(benignBig) + ' | base64)\n__FA_EOF__');

// C: hostile 140KB, chain with wc instead of cksum
run('C hostile-140KB +wc', 'cat <<__FA_EOF__ | base64 -d | wc -c\n$(printf %s ' + q(hostileBig) + ' | base64)\n__FA_EOF__');

// D: benign 140KB, chain with wc
run('D benign-140KB +wc', 'cat <<__FA_EOF__ | base64 -d | wc -c\n$(printf %s ' + q(benignBig) + ' | base64)\n__FA_EOF__');

// E: hostile 140KB, cat only (no pipe)
run('E hostile-140KB cat-only', 'cat <<__FA_EOF__\n$(printf %s ' + q(hostileBig) + ' | base64)\n__FA_EOF__');

// F: hostile SMALL, cksum chain
run('F hostile-small +cksum', 'cat <<__FA_EOF__ | base64 -d | cksum\n$(printf %s ' + q(hostileBig.slice(0, 100)) + ' | base64)\n__FA_EOF__');

